const { withAppBuildGradle } = require('expo/config-plugins');

// Never put secret values in Expo config. The generated Gradle script reads
// signing material only at build time, and refuses Expo's debug release key.
const signing = `
// DUDE preview signing (generated by with-preview-signing)
def dudeSigningNames = ['DUDE_ANDROID_KEYSTORE_PATH', 'DUDE_ANDROID_KEYSTORE_PASSWORD', 'DUDE_ANDROID_KEY_ALIAS', 'DUDE_ANDROID_KEY_PASSWORD']
// Inspect resolved tasks so aggregate/abbreviated requests cannot produce an
// unsigned release by avoiding "release" in the command-line task name.
gradle.taskGraph.whenReady { graph ->
    def dudeReleaseRequested = graph.allTasks.any { it.project == project && it.name.toLowerCase().contains('release') }
    if (dudeReleaseRequested && dudeSigningNames.any { !System.getenv(it)?.trim() }) {
        throw new GradleException('DUDE preview release requires protected Android signing configuration; debug signing is forbidden.')
    }
    if (dudeReleaseRequested && (!System.getenv('DUDE_ANDROID_VERSION_NAME') || !System.getenv('DUDE_ANDROID_VERSION_CODE'))) {
        throw new GradleException('DUDE preview release requires master-derived versionName and versionCode; use mobile:package.')
    }
}
android {
    signingConfigs {
        dudePreview {
            if (dudeSigningNames.every { System.getenv(it)?.trim() }) {
                storeFile file(System.getenv('DUDE_ANDROID_KEYSTORE_PATH'))
                storePassword System.getenv('DUDE_ANDROID_KEYSTORE_PASSWORD')
                keyAlias System.getenv('DUDE_ANDROID_KEY_ALIAS')
                keyPassword System.getenv('DUDE_ANDROID_KEY_PASSWORD')
            }
        }
    }
    buildTypes.release.signingConfig = signingConfigs.dudePreview
}
`;

function applySigning(contents) {
  const marker = '// DUDE preview signing (generated by with-preview-signing)';
  if (!contents.includes(marker)) return contents + signing;
  // Replace the owned block on repeated prebuilds, including the original
  // unbounded block, so regenerated projects pick up signing guard fixes.
  const block = /\n?\/\/ DUDE preview signing \(generated by with-preview-signing\)[\s\S]*?^\s*buildTypes\.release\.signingConfig = signingConfigs\.dudePreview\r?\n}\r?\n/m;
  if (!block.test(contents)) throw new Error('Cannot safely replace the generated DUDE preview signing block.');
  return contents.replace(block, signing);
}

module.exports = config => {
  const name = process.env.DUDE_ANDROID_VERSION_NAME;
  const code = process.env.DUDE_ANDROID_VERSION_CODE;
  if (name || code) {
    if (!/^\d+\.\d+\.\d+$/.test(name || '') || !/^\d+$/.test(code || '') || Number(code) < 1 || Number(code) > 2100000000) throw new Error('Invalid Android preview version configuration.');
    config.version = name;
    config.android = { ...config.android, versionCode: Number(code) };
  }
  return withAppBuildGradle(config, mod => {
    if (mod.modResults.language !== 'groovy') throw new Error('DUDE preview signing requires the Expo Groovy Android template.');
    mod.modResults.contents = applySigning(mod.modResults.contents);
    return mod;
  });
};
module.exports.applySigning = applySigning;
